import { useState } from 'react';

export function ConfirmDialog({ onConfirm }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button onClick={() => setOpen(true)} className="rounded bg-red-600 px-4 py-2 text-white">Delete</button>
      {open && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="w-full max-w-sm rounded-lg bg-white p-6">
            <h3 className="mb-2 text-lg font-semibold">Are you sure?</h3>
            <p className="mb-6 text-sm text-gray-600">{{message}}</p>
            <div className="flex justify-end gap-2">
              <button onClick={() => setOpen(false)} className="rounded border px-4 py-2">Cancel</button>
              <button onClick={() => { onConfirm(); setOpen(false); }} className="rounded bg-red-600 px-4 py-2 text-white">Delete</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}
